// th14_s2_w04 —— TH14 Stage 2 道中波 4：MainSub03（707-718）+ ECir00（8-43）+ ECir00_at（45-64）
// 三对 ECir00 于源帧 0/120/240 创建；每只敌 5 轮「自机狙减速移动 + 环状直线激光」，
// 激光条数与角步长按源 diffF/diffI 分档；Easy 的奇数轮不发。
const TIME_LIMIT: int = 2324;        // 120 开场 + 2200 排程/退场估计窗口 + 4 启动余量
const OPENING_BUFFER: int = 120;

// 源 etSprite(0, 20, 3)：目标激光只有一种截面贴图，color 原样取 3
const LASER_COLOR: int = 3;
// 源 laserNew(0, 0.0, 128.0, 0.0, 14.0)：L=128、w=14<32 → 原生半高 w/4=3.5 → 判定宽 7
const LASER_WIDTH: fx = 7fx;
// 源 etSpeed(0, 3.0, 3.0)：Line 先以 3px/帧长出再平移
const LASER_SPEED: fx = 3fx;
// Line 判定段 [0.1L, 0.9L]（L=128）→ 近端 12.8、棒长 102.4；生长/平移用 lz_speed 近似
const LASER_START: fx = 12.8fx;
const LASER_ROD: fx = 102.4fx;

// ECir00_at：源 etNew/etSprite/etAngle(A,A)/etSpeed/laserNew 后循环 C 次
// 「etAngle(A,0) → A+=B → laserOn」。A 为调用时快照（async 传参）；
// 每轮 C 根激光正好绕满 2π（4×π/2、6×π/3、10×π/5），故快照与传引用的后续角度一致。
async sub cir_at(a0: angle) {
    // 源 diffI($C, 4, 4, 6, 10)；步长 diffF(%B, π/2, π/2, π/3, π/5) = 2π/C
    var count: int = 4;
    var rank: int = global(GVAR_RANK);
    if rank == RANK_HARD {
        count = 6;
    } else if rank == RANK_LUNATIC {
        count = 10;
    }
    for i in 0..count {
        // 等分整周：第 i 根角 = A0 + i·(2π/C)，BAM 余数按整数除法分摊
        var ang: angle = a0 + ((i * 65536 / count) as angle);
        var h: int = laser(LASER_COLOR, $self_x, $self_y, ang, 0fx, LASER_WIDTH, 0, 9999, 0);
        lz_start(h, LASER_START);
        lz_speed(h, LASER_SPEED, LASER_ROD);
    }
}

// ECir00 主任务：源 8-43。5 轮循环（$C=5），$B 为轮号，%A 从 π/2 每轮 +π/4。
async sub cir_enemy() {
    set_invuln(65535);               // 训练外壳：真实敌无敌
    set_hurtbox(12fx);               // 源 setHurtbox(24,24) → 24×0.5
    set_hitbox(8fx);                 // 源 setHitbox(16,16) → 16×0.5，体碰照源保留
    var a: angle = 90deg;            // %A = 1.570796f
    for b in 0..5 {                  // 源 $C=5 的 if ($C--) 循环，共 5 轮
        // 源 moveVel(%ANGLE_PLAYER, 3.0) + moveSpeedTime(40, 1, 0.0)：朝自机匀速转向后减速到 0
        move_vel(0, aim_player(), 3fx, EASE_LINEAR);
        move_speed(40, 0fx, EASE_QUAD_IN);   // mode1 = t²
        wait(40);
        // 源 unless (($DIFF != 0) || (($B % 2) == 0)) goto skip：Easy 的奇数额外轮不发
        if (global(GVAR_RANK) != 0) || (b % 2 == 0) {
            spawn cir_at(a);
        }
        wait(60);
        a = a + 45deg;               // %A += 0.785398
    }
    wait(100);
    move_vel(0, -90deg, 4fx, EASE_LINEAR);   // 源 moveVel(-π/2, 4.0)：向上离场
    loop { wait(1000); }             // 源 wait(1000) 无限循环；越界后引擎回收
}

// MainSub03：源 707-718，源帧 0/120/240 各创建一对 ECir00（绝对坐标）
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(-128fx, -24fx, 300, 0, 1000, 0, cir_enemy);
    _ = spawn_enemy(128fx, -24fx, 300, 0, 1000, 0, cir_enemy);
    wait(120);
    _ = spawn_enemy(-160fx, -24fx, 300, 0, 1000, 0, cir_enemy);
    _ = spawn_enemy(160fx, -24fx, 300, 0, 1000, 0, cir_enemy);
    wait(120);
    _ = spawn_enemy(-64fx, -24fx, 300, 0, 1000, 0, cir_enemy);
    _ = spawn_enemy(64fx, -24fx, 300, 0, 1000, 0, cir_enemy);
    loop { wait(100); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
